// Meal history is browser-local and only records meals explicitly shared with the character.
if(!Array.isArray(state.mealHistory))state.mealHistory=[];
if(!state.mealHistoryMigrated){if(!state.mealHistory.length&&state.sharedMeal&&Number.isFinite(state.sharedMeal.createdAt))state.mealHistory.push({id:'previous-shared-meal',name:state.sharedMeal.name,food:state.sharedMeal.food,createdAt:state.sharedMeal.createdAt});state.mealHistoryMigrated=true;save()}
function recordSharedMeal(meal){state.mealHistory.push({id:crypto.randomUUID(),name:meal.name,food:meal.food,createdAt:meal.createdAt})}
(()=>{const originalRender=render,originalGo=go;let current=new Date(),selected=null;
const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function showCalendar(){const y=current.getFullYear(),m=current.getMonth(),first=new Date(y,m,1).getDay(),total=new Date(y,m+1,0).getDate();const groups={};for(const meal of state.mealHistory){const d=new Date(meal.createdAt);if(!Number.isFinite(d.getTime()))continue;const k=key(d);(groups[k]||=[]).push(meal)}const title=current.toLocaleDateString(undefined,{month:'long',year:'numeric'});const days=Array.from({length:first},()=>'<span class="calendar-blank" aria-hidden="true"></span>').join('')+Array.from({length:total},(_,i)=>{const d=new Date(y,m,i+1),k=key(d),count=groups[k]?.length||0;return `<button class="calendar-day ${count?'has-meals':''} ${selected===k?'selected':''}" data-cal-day="${k}" aria-label="${escapeHTML(d.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}))}, ${count} ${count===1?'meal':'meals'}" aria-pressed="${selected===k}"><span>${i+1}</span>${count?'<small>✦ '+count+'</small>':''}</button>`}).join('');const meals=groups[selected]||[];const details=selected?`<div class="calendar-detail"><h2>${escapeHTML(new Date(Number(selected.slice(0,4)),Number(selected.slice(5,7))-1,Number(selected.slice(8,10))).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}))}</h2>${meals.length?meals.slice().sort((a,b)=>a.createdAt-b.createdAt).map(meal=>`<article class="calendar-meal"><span>🍽</span><div><strong>${escapeHTML(meal.name)}</strong><small>${escapeHTML(new Date(meal.createdAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))} · ${escapeHTML(window.MellowMealAI.foods.find(f=>f.id===meal.food)?.name||'Shared meal')}</small></div><button class="text-link" data-remove-meal="${escapeHTML(meal.id)}">Delete</button></article>`).join(''):'<p>No meals shared on this day yet.</p>'}</div>`:'<div class="calendar-detail"><h2>Choose a day</h2><p>Colored dates have meals you shared with your companion.</p></div>';content.innerHTML=greeting('Little meals, remembered.','A calendar of the moments you’ve shared together.','MEAL CALENDAR')+`<div class="calendar-layout"><section class="card card-pad"><div class="calendar-header"><button class="secondary" id="cal-prev" aria-label="Previous month">←</button><h2>${escapeHTML(title)}</h2><button class="secondary" id="cal-next" aria-label="Next month">→</button></div><div class="calendar-grid calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${days}</div><p class="helper">✦ Highlighted days have shared meals. Stored only in this browser.</p></section><section class="card card-pad">${details}</section></div>`;$('#cal-prev').onclick=()=>{current=new Date(y,m-1,1);selected=null;showCalendar()};$('#cal-next').onclick=()=>{current=new Date(y,m+1,1);selected=null;showCalendar()};document.querySelectorAll('[data-cal-day]').forEach(b=>b.onclick=()=>{selected=b.dataset.calDay;showCalendar()});document.querySelectorAll('[data-remove-meal]').forEach(b=>b.onclick=()=>{state.mealHistory=state.mealHistory.filter(meal=>meal.id!==b.dataset.removeMeal);save();showCalendar()})}
render=function(){originalRender();if(page==='meal-calendar')showCalendar()};go=function(p){originalGo(p);if(p==='meal-calendar')$('#page-label').textContent='MEAL CALENDAR'};
})();
